import axios from "axios";
import { getTeamAbbr, round1, round3 } from "../utils/formatters";

// Static data files generated by GitHub Actions (served from same origin)
const BASE = import.meta.env.BASE_URL || "/";
const dataUrl = (path) => `${BASE}data/${path}`;

const staticFetch = (path) => axios.get(dataUrl(path)).then((r) => r.data);

// MLB API uses several distinct `detailedState` values for games that are
// over and won't resume — collapse them all to "Final" so downstream UI
// (ScheduleView, TodayGame, Scoreboard, MatchupView, etc.) treats them
// uniformly. Includes:
//   "Final"           — standard 9+ inning result
//   "Game Over"       — interim status briefly emitted between last out and final
//   "Completed Early" — rain-shortened, suspended-then-final, etc.
//   "Final: Tied"     — extremely rare ties (extra-inning rule changes, etc.)
// Anything else (Postponed, Cancelled, Suspended, Scheduled, In Progress…)
// passes through unchanged.
const TERMINAL_DETAILED_STATES = new Set([
  "Final",
  "Game Over",
  "Completed Early",
  "Final: Tied",
]);
export const isTerminalDetailedState = (s) => {
  if (!s) return false;
  if (TERMINAL_DETAILED_STATES.has(s)) return true;
  // MLB also emits forms like "Completed Early: Rain" — match the prefix.
  return s.startsWith("Completed Early") || s.startsWith("Final:");
};
export const normalizeStatus = (s) => (isTerminalDetailedState(s) ? "Final" : (s || ""));

// MLB API sometimes marks isScoringPlay=false when runs score on mid-AB events
// (e.g. pickoff errors, wild pitches, passed balls during a strikeout).
// Check runners array as fallback.
const didRunScore = (play) =>
  play.about?.isScoringPlay ||
  (play.runners || []).some((r) => r.details?.isScoringEvent);

// Build description for plays where the scoring event is a mid-AB runner event
// (the result.description won't mention the run scoring in these cases)
const scoringDescription = (play) => {
  const desc = play.result?.description || "";
  if (play.about?.isScoringPlay) return desc;
  const scoredRunners = (play.runners || [])
    .filter((r) => r.details?.isScoringEvent)
    .map((r) => r.details?.runner?.fullName || "");
  if (!scoredRunners.length) return desc;
  const event = (play.runners || [])
    .find((r) => r.details?.isScoringEvent)?.details?.event || "";
  const eventDesc = event.replace(/_/g, " ");
  const scored = scoredRunners.join(", ");
  return desc
    ? `${scored} scores on ${eventDesc.toLowerCase()}. ${desc}`
    : `${scored} scores on ${eventDesc.toLowerCase()}.`;
};

// MLB Stats API called directly from browser (no backend needed, free & fast)
const mlbApi = axios.create({
  baseURL: "https://statsapi.mlb.com/api/v1",
  timeout: 15000,
});

// ---- Static data (generated daily) ----
export const fetchRoster = async (teamId) => {
  const season = new Date().getFullYear();
  const resp = await mlbApi.get(`/teams/${teamId}/roster`, {
    params: { rosterType: "active", season },
  });
  return (resp.data.roster || []).map((entry) => {
    const p = entry.person || {};
    const pos = entry.position || {};
    return {
      id: p.id,
      fullName: p.fullName || "",
      jerseyNumber: entry.jerseyNumber || "",
      position: {
        code: pos.code || "",
        name: pos.name || "",
        type: pos.type || "",
        abbreviation: pos.abbreviation || "",
      },
      status: entry.status?.description || "Active",
      photoUrl: `https://img.mlbstatic.com/mlb-photos/image/upload/d_people:generic:headshot:67:current.png/w_213,q_auto:best/v1/people/${p.id}/headshot/67/current`,
    };
  });
};

// Full season schedule straight from the MLB Stats API. Previously we
// served a static per-team schedule.json generated once daily + merged
// in a last-7-days live scores call — which meant non-recently-updated
// static files showed stale records for games older than a week.
// Going live-only means every game's status + score is always current
// and we don't need to regenerate static per-team files.
//
// Returns an array matching the legacy static shape so existing
// consumers (ScheduleView, etc.) need no changes.
export const fetchSchedule = async (teamId) => {
  try {
    const season = new Date().getFullYear();
    const resp = await mlbApi.get("/schedule", {
      params: {
        sportId: 1,
        teamId,
        season,
        gameType: "R",
        hydrate: "team,linescore,venue,probablePitcher",
      },
    });
    // MLB returns postponed games TWICE — once on the original date with
    // detailedState="Postponed" and a rescheduleDate, and again on the
    // replay date with detailedState="Final" and rescheduledFrom set.
    // Dedupe by gamePk, keeping the row that best represents truth:
    //   Final > In Progress > Postponed/Cancelled/Suspended > Scheduled
    // That way, replayed games collapse onto their actual played date, and
    // still-postponed games (no replay yet) keep their Postponed row with
    // the rescheduleDate the UI can surface.
    const STATUS_PRIORITY = {
      "Final": 0,
      "Game Over": 0,
      "Completed Early": 0,
      "Final: Tied": 0,
      "In Progress": 1,
      "Suspended": 2,
      "Postponed": 3,
      "Cancelled": 3,
      "Delayed": 4,
      "Delayed Start": 4,
      "Warmup": 5,
      "Pre-Game": 5,
      "Scheduled": 6,
    };
    const prioFor = (s) => {
      if (s == null) return 99;
      if (STATUS_PRIORITY[s] !== undefined) return STATUS_PRIORITY[s];
      // Match the same terminal-state prefixes normalizeStatus does.
      if (isTerminalDetailedState(s)) return 0;
      return 99;
    };
    const byPk = new Map();
    for (const date of resp.data?.dates || []) {
      for (const g of date.games || []) {
        const prev = byPk.get(g.gamePk);
        const prevPrio = prev ? prioFor(prev.status?.detailedState) : 99;
        const thisPrio = prioFor(g.status?.detailedState);
        if (!prev || thisPrio < prevPrio) byPk.set(g.gamePk, g);
      }
    }
    const games = [];
    for (const g of byPk.values()) {
      const away = g.teams?.away || {};
      const home = g.teams?.home || {};
      const at = away.team || {};
      const ht = home.team || {};
      const detailedState = g.status?.detailedState || "";
      const status = normalizeStatus(detailedState);
      const isFinal = status === "Final";
      const awayScore = away.score ?? null;
      const homeScore = home.score ?? null;
      games.push({
        gamePk: g.gamePk,
        gameDate: g.gameDate,
        status,
        detailedState,                            // raw MLB state for UI badges
        rescheduleDate: g.rescheduleDate || null, // set when still postponed
        rescheduledFrom: g.rescheduledFrom || null, // set on the replay row
        venue: {
          id: g.venue?.id,
          name: g.venue?.name || "",
        },
        away: {
          id: at.id,
          name: at.name || "",
          abbreviation: at.abbreviation || "",
          score: awayScore,
          isWinner: isFinal && awayScore != null && homeScore != null
            ? awayScore > homeScore
            : false,
          probablePitcher: away.probablePitcher
            ? { id: away.probablePitcher.id, fullName: away.probablePitcher.fullName }
            : null,
          logoUrl: at.id ? `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${at.id}.svg` : "",
        },
        home: {
          id: ht.id,
          name: ht.name || "",
          abbreviation: ht.abbreviation || "",
          score: homeScore,
          isWinner: isFinal && awayScore != null && homeScore != null
            ? homeScore > awayScore
            : false,
          probablePitcher: home.probablePitcher
            ? { id: home.probablePitcher.id, fullName: home.probablePitcher.fullName }
            : null,
          logoUrl: ht.id ? `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${ht.id}.svg` : "",
        },
      });
    }
    // Re-sort by gameDate since dedupe may have picked later-dated rows.
    games.sort((a, b) => new Date(a.gameDate) - new Date(b.gameDate));
    return games;
  } catch {
    // Fallback to static JSON if API call fails (offline, rate-limited, etc.)
    try { return await staticFetch(`teams/${getTeamAbbr(teamId)}/schedule.json`); }
    catch { return []; }
  }
};

