// Fetch lineup for a game — returns actual lineup if posted, null if not yet available
export const fetchGameLineup = async (gamePk, teamId) => {
  try {
    const resp = await mlbApi.get(`/game/${gamePk}/boxscore`);
    const teams = resp.data?.teams || {};
    const side = teams.home?.team?.id === teamId ? teams.home : teams.away;
    const order = side?.battingOrder || [];
    if (!order.length) return null;

    const players = side.players || {};
    return order.map((pid, i) => {
      const p = players[`ID${pid}`] || {};
      const person = p.person || {};
      const pos = p.position || {};
      const batting = p.seasonStats?.batting || {};
      return {
        id: pid,
        fullName: person.fullName || "",
        position: pos.abbreviation || "",
        avg: batting.avg || ".000",
        order: i + 1,
      };
    });
  } catch {
    return null;
  }
};

// Projected lineup: use recent game boxscores, fallback to roster-based projection
export const fetchProjectedLineup = async (teamId) => {
  try {
    // Try to build lineup from recent games
    const today = new Date();
    const startDate = new Date(today);
    startDate.setDate(startDate.getDate() - 14);
    const startStr = `${startDate.getFullYear()}-${String(startDate.getMonth()+1).padStart(2,"0")}-${String(startDate.getDate()).padStart(2,"0")}`;
    const endStr = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,"0")}-${String(today.getDate()).padStart(2,"0")}`;

    const schedResp = await mlbApi.get("/schedule", {
      params: { teamId, sportId: 1, startDate: startStr, endDate: endStr, gameType: "R", hydrate: "linescore" },
    });

    const recentGames = [];
    for (const date of schedResp.data?.dates || []) {
      for (const g of date.games || []) {
        if (isTerminalDetailedState(g.status?.detailedState)) {
          recentGames.push(g.gamePk);
        }
      }
    }

    // Get batting orders from recent games (last 5 max)
    const gamePks = recentGames.slice(-5);
    if (gamePks.length > 0) {
      const lineups = await Promise.all(
        gamePks.map(async (gpk) => {
          try {
            const resp = await mlbApi.get(`/game/${gpk}/boxscore`);
            const teams = resp.data?.teams || {};
            const side = teams.home?.team?.id === Number(teamId) ? teams.home : teams.away;
            const order = side?.battingOrder || [];
            if (order.length < 9) return null;
            const players = side?.players || {};
            return order.slice(0, 9).map((id, i) => {
              const p = players[`ID${id}`];
              return {
                id,
                fullName: p?.person?.fullName || "",
                position: p?.position?.abbreviation || "",
                avg: p?.seasonStats?.batting?.avg || ".000",
                order: i + 1,
                projected: true,
              };
            });
          } catch { return null; }
        })
      );

      // Use the most recent valid lineup
      const validLineups = lineups.filter(Boolean);
      if (validLineups.length > 0) {
        return validLineups[validLineups.length - 1];
      }
    }

    // Fallback: position-based projection
    const roster = await fetchRoster(teamId);
    const posPlayers = roster.filter((p) => p.position.type !== "Pitcher");
    const posOrder = ["CF", "SS", "RF", "1B", "DH", "3B", "LF", "2B", "C"];
    const picked = [];
    const used = new Set();
    for (const pos of posOrder) {
      const candidate = posPlayers.find((p) => p.position.abbreviation === pos && !used.has(p.id));
      if (candidate) { picked.push(candidate); used.add(candidate.id); }
    }
    for (const p of posPlayers) {
      if (picked.length >= 9) break;
      if (!used.has(p.id)) { picked.push(p); used.add(p.id); }
    }
    return picked.slice(0, 9).map((p, i) => ({
      id: p.id, fullName: p.fullName, position: p.position.abbreviation,
      avg: ".000", order: i + 1, projected: true,
    }));
  } catch (e) {
    return null;
  }
};

// Fetch live game state: current batter/pitcher, inning, count, outs, linescore, last play
export const fetchLiveGameState = async (gamePk) => {
  try {
    const resp = await axios.get(`https://statsapi.mlb.com/api/v1.1/game/${gamePk}/feed/live`, { timeout: 10000 });
    const ld = resp.data?.liveData || {};
    const ls = ld.linescore || {};
    const plays = ld.plays || {};
    const cp = plays.currentPlay?.matchup || {};
    const teams = ls.teams || {};

    // Find pitcher's game stats from boxscore
    const pitcherId = cp.pitcher?.id;
    let pitcherGameStats = null;
    if (pitcherId) {
      const box = ld.boxscore?.teams || {};
      for (const side of ["away", "home"]) {
        const p = box[side]?.players?.[`ID${pitcherId}`];
        if (p) {
          const ps = p.stats?.pitching || {};
          const seasonPitching = p.seasonStats?.pitching || {};
          pitcherGameStats = {
            ip: ps.inningsPitched || "0",
            pitches: ps.numberOfPitches || 0,
            strikes: ps.strikes || 0,
            k: ps.strikeOuts || 0,
            h: ps.hits || 0,
            er: ps.earnedRuns || 0,
            era: seasonPitching.era || "—",
          };
          break;
        }
      }
    }

    // Find batter's season avg from boxscore
    const batterId = cp.batter?.id;
    let batterAvg = null;
    if (batterId) {
      const box = ld.boxscore?.teams || {};
      for (const side of ["away", "home"]) {
        const p = box[side]?.players?.[`ID${batterId}`];
        if (p) {
          batterAvg = p.seasonStats?.batting?.avg || ".000";
          break;
        }
      }
    }

    // Get game batting line for a player from boxscore
    const getGameBattingLine = (boxscore, playerId) => {
      if (!boxscore || !playerId) return {};
      const box = boxscore.teams || {};
      for (const side of ["away", "home"]) {
        const p = box[side]?.players?.[`ID${playerId}`];
        if (p) {
          const s = p.stats?.batting || {};
          return { ab: s.atBats || 0, h: s.hits || 0, hr: s.homeRuns || 0, rbi: s.rbi || 0, k: s.strikeOuts || 0, bb: s.baseOnBalls || 0, hbp: s.hitByPitch || 0, sb: s.stolenBases || 0 };
        }
      }
      return {};
    };

    // Last completed play
    const allPlays = plays.allPlays || [];
    const completed = allPlays.filter((p) => p.result?.event);
    const lastPlay = completed.length > 0 ? completed[completed.length - 1].result.description : null;

    return {
      inning: ls.currentInning || null,
      inningHalf: ls.inningHalf || "",
      // inningState is more granular than inningHalf — covers Top/Middle/
      // Bottom/End so we can render "Mid 4th" or "End 2nd" between halves.
      // Falls back to inningHalf when MLB doesn't expose the state field.
      inningState: ls.inningState || ls.inningHalf || "",
      outs: ls.outs ?? 0,
      balls: ls.balls ?? 0,
      strikes: ls.strikes ?? 0,
      onFirst: !!ls.offense?.first,
      onSecond: !!ls.offense?.second,
      onThird: !!ls.offense?.third,
      runnerFirst: ls.offense?.first ? { id: ls.offense.first.id, fullName: ls.offense.first.fullName } : null,
      runnerSecond: ls.offense?.second ? { id: ls.offense.second.id, fullName: ls.offense.second.fullName } : null,
      runnerThird: ls.offense?.third ? { id: ls.offense.third.id, fullName: ls.offense.third.fullName } : null,
      batter: cp.batter ? { id: cp.batter.id, fullName: cp.batter.fullName, avg: batterAvg, ...getGameBattingLine(ld.boxscore, cp.batter.id) } : null,
      pitcher: cp.pitcher ? { id: cp.pitcher.id, fullName: cp.pitcher.fullName, gameStats: pitcherGameStats } : null,
      lastPlay,
      lastHitData: (() => {
        // Try completed plays first
        const lastAB = completed.length > 0 ? completed[completed.length - 1] : null;
        const extractRunners = (play) => (play.runners || []).map((r) => ({
          name: r.details?.runner?.fullName || "",
          start: r.movement?.start || null, // null = batter from home
          end: r.movement?.end || null,      // "1B","2B","3B","score", null = out
          isOut: r.movement?.isOut || false,
        }));

        if (lastAB) {
          const hitEvent = (lastAB.playEvents || []).find((e) => e.hitData?.coordinates?.coordX);
          if (hitEvent) {
            const hd = hitEvent.hitData;
            return {
              x: hd.coordinates.coordX,
              y: hd.coordinates.coordY,
              exitVelo: hd.launchSpeed,
              launchAngle: hd.launchAngle,
              distance: hd.totalDistance ? Math.round(hd.totalDistance) : null,
              trajectory: hd.trajectory,
              event: lastAB.result?.event || "",
              description: lastAB.result?.description || "",
              batterName: lastAB.matchup?.batter?.fullName || "",
              runners: extractRunners(lastAB),
            };
          }
        }
        const cp2 = plays.currentPlay;
        if (cp2?.result?.event) {
          const hitEvent = (cp2.playEvents || []).find((e) => e.hitData?.coordinates?.coordX);
          if (hitEvent) {
            const hd = hitEvent.hitData;
            return {
              x: hd.coordinates.coordX,
              y: hd.coordinates.coordY,
              exitVelo: hd.launchSpeed,
              launchAngle: hd.launchAngle,
              distance: hd.totalDistance ? Math.round(hd.totalDistance) : null,
              trajectory: hd.trajectory,
              event: cp2.result.event,
              description: cp2.result.description || "",
              batterName: cp2.matchup?.batter?.fullName || "",
              runners: extractRunners(cp2),
            };
          }
        }
        return null;
      })(),
      currentAtBat: (plays.currentPlay?.playEvents || [])
        .filter((e) => e.details?.description && e.details?.call?.description)
        .map((e) => {
          const d = e.details;
          const speed = e.pitchData?.startSpeed;
          const pitchType = d.type?.description || "";
          const call = d.call?.description || d.description || "";
          const batterName = cp.batter?.fullName || "";
          let action = "";
          if (d.isStrike && d.code === "C") action = `${batterName} takes`;
          else if (d.isStrike && d.code === "S") action = `${batterName} swings and misses`;
          else if (d.isStrike && d.code === "F") action = `${batterName} fouls off`;
          else if (d.isBall) action = `${batterName} takes`;
          else if (d.isInPlay) action = `${batterName} puts in play`;
          else action = batterName;
          const pitchInfo = pitchType ? `${pitchType}${speed ? ` ${speed} mph` : ""}` : "";
          const hd = e.hitData || {};
          const hitData = d.isInPlay && hd.coordinates?.coordX ? {
            x: hd.coordinates.coordX,
            y: hd.coordinates.coordY,
            exitVelo: hd.launchSpeed,
            launchAngle: hd.launchAngle,
            distance: hd.totalDistance ? Math.round(hd.totalDistance) : null,
            trajectory: hd.trajectory,
          } : null;
          const pCoords = e.pitchData?.coordinates;
          const pitch = {
            action, pitchInfo, call, hitData, code: d.code || "",
            pX: pCoords?.pX ?? null,
            pZ: pCoords?.pZ ?? null,
            szTop: e.pitchData?.strikeZoneTop ?? null,
            szBot: e.pitchData?.strikeZoneBottom ?? null,
            isBall: !!d.isBall, isStrike: !!d.isStrike, isInPlay: !!d.isInPlay,
            count: e.count ? `${e.count.balls}-${e.count.strikes}` : null,
          };
          return pitch;
        })
        ,
      currentPlayComplete: !!plays.currentPlay?.result?.event,
      onDeck: ls.offense?.onDeck ? { id: ls.offense.onDeck.id, fullName: ls.offense.onDeck.fullName, ...getGameBattingLine(ld.boxscore, ls.offense.onDeck.id) } : null,
      inHole: ls.offense?.inHole ? { id: ls.offense.inHole.id, fullName: ls.offense.inHole.fullName, ...getGameBattingLine(ld.boxscore, ls.offense.inHole.id) } : null,
      scoringPlays: allPlays
        .filter(didRunScore)
        .map((p) => {
          const hitEv = (p.playEvents || []).find((e) => e.hitData?.coordinates?.coordX);
          const hd = hitEv?.hitData;
          // Extract pre-play runner state from runners array
          const runners = p.runners || [];
          const runnersOn = { first: false, second: false, third: false };
          const runnerNames = {};
          for (const r of runners) {
            const origin = r.movement?.originBase || r.movement?.start;
            const name = r.details?.runner?.fullName || "";
            if (origin === "1B") { runnersOn.first = true; runnerNames.first = name; }
            else if (origin === "2B") { runnersOn.second = true; runnerNames.second = name; }
            else if (origin === "3B") { runnersOn.third = true; runnerNames.third = name; }
          }
          return {
            inning: p.about?.inning || 0,
            halfInning: p.about?.halfInning || "",
            description: scoringDescription(p),
            event: p.result?.event || "",
            awayScore: p.result?.awayScore ?? 0,
            homeScore: p.result?.homeScore ?? 0,
            hrDistance: hd?.totalDistance ? Math.round(hd.totalDistance) : null,
            runnersOn,
            runnerNames,
            hitData: hd ? {
              x: hd.coordinates.coordX,
              y: hd.coordinates.coordY,
              exitVelo: hd.launchSpeed,
              launchAngle: hd.launchAngle,
              distance: hd.totalDistance ? Math.round(hd.totalDistance) : null,
              trajectory: hd.trajectory,
              event: p.result?.event || "",
              description: p.result?.description || "",
              batterName: p.matchup?.batter?.fullName || "",
              runners: runners.map((r) => ({
                name: r.details?.runner?.fullName || "",
                start: r.movement?.start || null,
                end: r.movement?.end || null,
                isOut: r.movement?.isOut || false,
              })),
            } : null,
          };
        }),
      linescore: {
        innings: (ls.innings || []).map((inn) => ({ num: inn.num, away: inn.away?.runs ?? "", home: inn.home?.runs ?? "" })),
        away: { runs: teams.away?.runs ?? 0, hits: teams.away?.hits ?? 0, errors: teams.away?.errors ?? 0 },
        home: { runs: teams.home?.runs ?? 0, hits: teams.home?.hits ?? 0, errors: teams.home?.errors ?? 0 },
      },
    };
  } catch {
    return null;
  }
};

