// PrizePicks hitter scoring table — kept in sync with the backend constant
// in backend/app/services/fantasy.py. Used to compute LIVE fantasy scores
// from in-progress boxscores directly in the browser (no backend needed).
const PP_SCORING = {
  single: 3,
  double: 5,
  triple: 8,
  home_run: 10,
  run: 2,
  rbi: 2,
  walk: 2,
  hbp: 2,
  sb: 5,
};

function _scoreFromBattingStat(s) {
  if (!s) return 0;
  const n = (v) => {
    const x = typeof v === "number" ? v : parseInt(v || 0, 10);
    return Number.isFinite(x) ? x : 0;
  };
  const hits = n(s.hits);
  const doubles = n(s.doubles);
  const triples = n(s.triples);
  const hr = n(s.homeRuns);
  const singles = Math.max(0, hits - doubles - triples - hr);
  return (
    PP_SCORING.single * singles +
    PP_SCORING.double * doubles +
    PP_SCORING.triple * triples +
    PP_SCORING.home_run * hr +
    PP_SCORING.run * n(s.runs) +
    PP_SCORING.rbi * n(s.rbi) +
    PP_SCORING.walk * n(s.baseOnBalls) +
    PP_SCORING.hbp * n(s.hitByPitch) +
    PP_SCORING.sb * n(s.stolenBases)
  );
}

// Live + Final fantasy scores for every batter in an in-progress or already-
// finished game today. Returns
//   { [playerId: number]: { efp: number, gamePk: number, status: string,
//                            state: "live" | "final" } }
// Scheduled games (not yet started) are absent. Live games drive the red
// border + "● LIVE X.X" chip; Final games drive the neutral "FINAL X.X" chip
// so users can see how their pick ended up.
export const fetchLiveFantasyScores = async () => {
  try {
    const d = new Date();
    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    const schedResp = await mlbApi.get("/schedule", {
      params: { sportId: 1, date: dateStr, gameType: "R" },
    });
    const LIVE_STATES = new Set([
      "In Progress",
      "Manager Challenge",
      "Delayed",
      "Delayed Start",
      "Warmup",
    ]);
    const FINAL_STATES = new Set(["Final", "Game Over", "Completed Early"]);
    const games = [];
    for (const dateEntry of schedResp.data?.dates || []) {
      for (const g of dateEntry.games || []) {
        const status = g.status?.detailedState || "";
        if (LIVE_STATES.has(status)) {
          games.push({ gamePk: g.gamePk, status, state: "live" });
        } else if (FINAL_STATES.has(status)) {
          games.push({ gamePk: g.gamePk, status, state: "final" });
        }
      }
    }
    if (games.length === 0) return {};

    const boxPerGame = await Promise.all(
      games.map(async (g) => {
        try {
          const r = await mlbApi.get(`/game/${g.gamePk}/boxscore`);
          const rows = {};
          for (const side of ["away", "home"]) {
            const players = r.data?.teams?.[side]?.players || {};
            for (const key of Object.keys(players)) {
              if (!key.startsWith("ID")) continue;
              const p = players[key];
              const stat = p?.stats?.batting;
              if (!stat || !stat.plateAppearances) continue;
              const pid = p?.person?.id;
              if (!pid) continue;
              rows[pid] = {
                efp: Number(_scoreFromBattingStat(stat).toFixed(2)),
                gamePk: g.gamePk,
                status: g.status,
                state: g.state,
              };
            }
          }
          return rows;
        } catch {
          return {};
        }
      })
    );
    return Object.assign({}, ...boxPerGame);
  } catch {
    return {};
  }
};

// Today's confirmed lineups keyed by teamId. Returns a plain object
//   { [teamId: number]: number[] }  -- array of starter player IDs per team.
// Teams that haven't posted a lineup yet are absent from the result (so
// the caller can tell "no lineup posted" from "empty lineup"). Hits MLB
// directly — static files don't have live lineup info, and the daily
// GH Action regenerates too infrequently to be useful here.
export const fetchTodayLineups = async () => {
  try {
    const d = new Date();
    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    const resp = await mlbApi.get("/schedule", {
      params: {
        sportId: 1,
        date: dateStr,
        hydrate: "lineups,team",
        gameType: "R",
      },
    });
    const byTeam = {};
    for (const dateEntry of resp.data?.dates || []) {
      for (const g of dateEntry.games || []) {
        const lineups = g.lineups || {};
        const awayTeamId = g.teams?.away?.team?.id;
        const homeTeamId = g.teams?.home?.team?.id;
        const extract = (side, teamId) => {
          if (!teamId) return;
          const arr = lineups[`${side}Players`] || lineups[side] || [];
          if (!Array.isArray(arr) || arr.length === 0) return;
          const ids = [];
          for (const p of arr) {
            const pid = p?.id || p?.person?.id;
            if (pid) ids.push(Number(pid));
          }
          if (ids.length > 0) byTeam[Number(teamId)] = ids;
        };
        extract("away", awayTeamId);
        extract("home", homeTeamId);
      }
    }
    return byTeam;
  } catch {
    return {};
  }
};

